-- Прогон 01_siege_lock.sql без следов: ставит новую функцию, берёт клан со штабом и монетами, проверяет три случая
-- и всегда заканчивается ошибкой «DRYRUN (всё откатано)», так что ничего не остаётся. Одна строка: так её можно
-- набрать в SQL-редакторе Supabase.
do $d$ declare v_clan bigint; v_terr text; v_bal int; r text := ''; begin set local lock_timeout = '3s'; execute $q$ create or replace function public._clan_treasury_spend(p_clan_id bigint, p_amount int, p_kind text, p_user uuid, p_label text) returns void language plpgsql security definer set search_path = public as $f$ begin if p_kind <> 'looted' and exists (select 1 from public.clan_sieges s where s.clan_id = p_clan_id) then raise exception 'CLAN:siege_lock'; end if; update public.clan_treasury set balance = balance - p_amount where clan_id = p_clan_id and balance >= p_amount; if not found then raise exception 'CLAN:no_funds'; end if; insert into public.clan_treasury_log (clan_id, kind, amount, user_id, label) values (p_clan_id, p_kind, -p_amount, p_user, p_label); end $f$ $q$; select h.clan_id, h.territory_id, t.balance into v_clan, v_terr, v_bal from public.clan_hq h join public.clan_treasury t on t.clan_id = h.clan_id where t.balance >= 2 and not exists (select 1 from public.clan_sieges s where s.clan_id = h.clan_id) limit 1; if v_clan is null then raise exception 'DRYRUN: no clan with an HQ and coins'; end if; perform public._clan_treasury_spend(v_clan, 1, 'spend_goal', null, 'dryrun'); r := r || '1) без осады трата прошла; '; insert into public.clan_sieges (territory_id, clan_id, attacker_id, ends_at) values (v_terr, v_clan, null, now() + interval '90 minutes'); begin perform public._clan_treasury_spend(v_clan, 1, 'spend_goal', null, 'dryrun'); r := r || '2) ОШИБКА: в осаде трата прошла; '; exception when others then r := r || '2) в осаде отказ: ' || sqlerrm || '; '; end; begin perform public._clan_treasury_spend(v_clan, 1, 'looted', null, 'dryrun'); r := r || '3) добыча при падении списывается; '; exception when others then r := r || '3) ОШИБКА, добыча: ' || sqlerrm || '; '; end; raise exception 'DRYRUN (всё откатано): клан %, баланс %; %', v_clan, v_bal, r; end $d$;
